import { APP_TIME_ZONE } from "./constants.ts";

/** Year and month (1–12) of a date in Lagos time. */
export function lagosYearMonth(now: Date = new Date()): { year: number; month: number } {
  const parts = new Intl.DateTimeFormat("en-GB", { timeZone: APP_TIME_ZONE, year: "numeric", month: "numeric" })
    .formatToParts(now)
    .reduce<Record<string, string>>((acc, p) => ({ ...acc, [p.type]: p.value }), {});
  return { year: Number(parts.year), month: Number(parts.month) };
}

export const ADULT_AGE = 18;

/**
 * 18+ check from birth month and year only (F0-FR2, 08 §3). We don't know the day, so the
 * birth month itself counts as "not yet": someone born in October 2008 is treated as 18 only
 * from November 2026. This is the safer reading (12 §4 Q16).
 */
export function isAdultByBirthMonth(birthYear: number, birthMonth: number, now: Date = new Date()): boolean {
  const today = lagosYearMonth(now);
  const fullMonthsSinceBirthMonth = (today.year - birthYear) * 12 + (today.month - birthMonth);
  return fullMonthsSinceBirthMonth > ADULT_AGE * 12;
}

/** A birth month/year is plausible if it is not in the future and not before 1900. */
export function isPlausibleBirthMonth(birthYear: number, birthMonth: number, now: Date = new Date()): boolean {
  if (!Number.isInteger(birthYear) || !Number.isInteger(birthMonth)) return false;
  if (birthMonth < 1 || birthMonth > 12 || birthYear < 1900) return false;
  const today = lagosYearMonth(now);
  return birthYear < today.year || (birthYear === today.year && birthMonth <= today.month);
}
